def canon(x): return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
def digest(x): return hashlib.sha256(x).hexdigest()
PROVENANCE={'identity':'/root/ml_blind_dated_group1','role':'independent mathematical derivation reviewer','context_isolation':'Derived solely from the six specified README.md and questions.json packets, including supplied inline tables/SVG markup. No repository solutions, source HTML, fragments, existing reviews/harnesses, memory, external web answers, or other worker outputs were consulted. No reference comparison performed.','tools':'Own algebra and proofs; system Python with SymPy for exact matrix arithmetic and symbolic residuals. This file contains the complete calculation process.','approval_status':'independent_results_only_no_reference_comparison_no_approval'}
def sub(i,method,derivation,conclusion,checks,unresolved=None):
 return {'subpart_id':i,'method':method,'derivation':derivation,'conclusion':conclusion,'checks':checks,'unresolved':unresolved or []}
def save(pack_id,answers):
 path=SOURCE/pack_id/'questions.json'; raw=path.read_bytes(); packet=json.loads(raw)
 computed_q=digest(canon(packet['questions']))
 assert computed_q==packet['question_payload_sha256']
 assert digest(canon({k:v for k,v in packet.items() if k!='packet_payload_sha256'}))==packet['packet_payload_sha256']
 assert set(answers)=={q['id'] for q in packet['questions']}
 results=[]
 for q in packet['questions']:
  assert digest(canon({k:v for k,v in q.items() if k!='input_sha256'}))==q['input_sha256']
  assert [x['subpart_id'] for x in answers[q['id']]]==q['subpart_ids']
  results.append({'id':q['id'],'input_sha256':q['input_sha256'],'subparts':answers[q['id']],'unresolved':[u for a in answers[q['id']] for u in a['unresolved']]})
 data={'schema_version':1,'pack_id':pack_id,'source_packet':str(path),'source_packet_file_sha256':digest(raw),'packet_payload_sha256':packet['packet_payload_sha256'],'question_payload_sha256':packet['question_payload_sha256'],'reviewer':PROVENANCE,'results':results,'unresolved':[{'id':r['id'],'items':r['unresolved']} for r in results if r['unresolved']]}
 (OUT/(pack_id+'-results.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 PACKS.append(data)
 print('Persisted',pack_id,len(results),'questions',sum(len(r['subparts']) for r in results),'subparts')

