 md.extend(['## Pack '+p['pack_id'],'','Packet payload SHA-256: '+p['packet_payload_sha256'],'','Question payload SHA-256: '+p['question_payload_sha256'],''])
 for r in p['results']:
  md.extend(['### '+r['id'],'','Input SHA-256: '+r['input_sha256'],''])
  for a in r['subparts']:
   md.extend(['#### '+a['subpart_id']+' ('+a['method']+')',''])
